use blit_core::copy::{resume_copy_file, resume_copy_from};
use std::fs::{self, File};
use std::os::unix::fs::PermissionsExt;
use std::path::Path;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let work = std::env::args_os().nth(1).expect("fixture folder");
    let directory = Path::new(&work);
    let src = directory.join("read-only-source");
    let dst = directory.join("interrupted-partial");
    fs::write(&src, vec![1u8; 8192])?;
    fs::set_permissions(&src, fs::Permissions::from_mode(0o444))?;
    let first = resume_copy_from(&mut File::open(&src)?, 12288, &dst, 4096);
    println!("first_error={:?}", first.err().map(|e| e.to_string()));
    println!("partial_mode={:04o}, bytes={}", fs::metadata(&dst)?.permissions().mode() & 0o7777, fs::metadata(&dst)?.len());
    println!("retry={:?}", resume_copy_file(&src, &dst, 4096));
    Ok(())
}
