        &std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_or(0, |since| since.as_nanos())
            .to_le_bytes(),
    );
    let mut ticket = [0u8; TICKET_BYTES];
    ticket.copy_from_slice(&hasher.finalize().as_bytes()[..TICKET_BYTES]);
    ticket
