    }
    static ORDER: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let ticket = new_ticket();
    kept.insert(
        ticket,
        Kept {
            state: State::Open(account),
            since: Instant::now(),
            order: ORDER.fetch_add(1, std::sync::atomic::Ordering::Relaxed),
        },
    );
    Some(ticket)
