use blit_core::generated::FileHeader;
use blit_core::remote::transfer::sink::{FsSinkConfig, FsTransferSink, TransferSink};
use std::future::Future;
use std::path::PathBuf;
use std::task::{Context, Poll, Waker};
use std::time::Duration;

fn main() {
    let root = PathBuf::from(std::env::args_os().nth(1).unwrap());
    std::fs::create_dir(&root).unwrap();
    let sink = FsTransferSink::new(root.clone(), root.clone(), FsSinkConfig { ignore_existing: true, ..Default::default() });
    let header = FileHeader { relative_path: "ordinary-file".into(), size: 10, ..Default::default() };
    let path = root.join(&header.relative_path);
    let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap();
    runtime.block_on(async {
        let mut opening = Box::pin(sink.begin_record(&header));
        let mut cx = Context::from_waker(Waker::noop());
        for _ in 0..100 {
            match opening.as_mut().poll(&mut cx) {
                Poll::Ready(_) => { println!("begin_record returned before cancellation"); return; }
                Poll::Pending => {
                    tokio::time::sleep(Duration::from_millis(10)).await;
                    if path.exists() {
                        drop(opening);
                        tokio::time::sleep(Duration::from_millis(10)).await;
                        println!("after cancellation: {:?}", std::fs::metadata(&path).map(|file| file.len()));
                        return;
                    }
                }
            }
        }
        panic!("file creation was never observed");
    });
}
